import React, { useState, useEffect } from 'react';
import { supabase } from '../supabaseClient';

function ClientePublico() {
  const [abaAtiva, setAbaAtiva] = useState('servicos');
  const [mesAtual, setMesAtual] = useState(new Date());
  const [agendamentoConfirmado, setAgendamentoConfirmado] = useState(null);
  const [carregando, setCarregando] = useState(false);
  const [avisoPolítica, setAvisoPolítica] = useState(false);
  const [horariosOcupados, setHorariosOcupados] = useState({});
  const [pontosCliente, setPontosCliente] = useState(0);
  const [usarPontos, setUsarPontos] = useState(false);
  const [carregandoPontos, setCarregandoPontos] = useState(false);
  const [diaHorarioSelecionado, setDiaHorarioSelecionado] = useState(null);

  const [dadosAgendamento, setDadosAgendamento] = useState({
    nome: '',
    email: '',
    telefone: '',
    profissional: '',
    hora: '',
    servico: '',
    data: ''
  });

  const [avaliacoes, setAvaliacoes] = useState([
    { id: 1, nome: 'João Silva', estrelas: 5, texto: 'Excelente atendimento! Marco é o melhor barbeiro!', data: '2026-07-25' },
    { id: 2, nome: 'Carlos Santos', estrelas: 5, texto: 'Ambiente perfeito e profissionais incríveis!', data: '2026-07-20' },
  ]);
  const [novaAvaliacao, setNovaAvaliacao] = useState({
    nome: '',
    estrelas: 5,
    texto: ''
  });

  const servicos = [
    { id: 1, uuid: '3f905b1f-61b6-4749-870a-cbe485e39fec', nome: 'Corte', preco: 4000, duracao: '45 min', descricao: 'Corte de cabelo masculino', imagem: '/images/servico_corte.png' },
    { id: 2, uuid: '68b86906-5816-4532-a4ac-6487531f872f', nome: 'Corte + Sobrancelhas', preco: 4500, duracao: '45 min', descricao: 'Corte completo com design de sobrancelhas', imagem: '/images/servico_corte_sobrancelhas.png' },
    { id: 3, uuid: 'b38f864d-e4f6-44e3-a03b-4706c7984306', nome: 'Corte + Barba', preco: 6500, duracao: '60 min', descricao: 'Corte e modelagem profissional de barba', imagem: '/images/servico_corte_barba.png' },
    { id: 4, uuid: '21a0d4eb-ee51-4124-a84b-34c3bdf307dc', nome: 'Coloração', preco: 15000, duracao: '90 min', descricao: 'Coloração profissional com tratamento', imagem: '/images/servico_coloracao.png' },
    { id: 5, uuid: '2f4ab333-ba87-40f5-9c3a-3dd911104130', nome: 'Alisamento', preco: 15000, duracao: '90 min', descricao: 'Alisamento e tratamento capilar', imagem: '/images/servico_alisamento.png' },
    { id: 6, uuid: '3ccdf5fc-eda5-4c09-9d19-19bcb7ee044a', nome: 'Corte Feminino', preco: 4000, duracao: '45 min', descricao: 'Corte moderno feminino', imagem: '/images/servico_corte_feminino.png' },
    { id: 7, uuid: '47d96756-2f6c-48ed-82f6-da80e0166b96', nome: 'Permanente', preco: 6000, duracao: '60 min', descricao: 'Permanente enrolado profissional', imagem: '/images/servico_permanente.png' },
    { id: 8, uuid: '1b3d936d-e4ff-4ab0-8bb5-78c6139230c2', nome: 'Limpeza de Pele', preco: 5000, duracao: '45 min', descricao: 'Limpeza facial profunda', imagem: '/images/servico_limpeza_pele.png' },
  ];

  const profissionais = [
    { 
      id: 1, 
      uuid: '11c0c7fb-e020-4c49-ab0a-28a16109b35f',
      nome: 'Marco Kaizen', 
      especialidade: 'Especialista em Cortes e Barba',
      qualificacoes: ['14 anos de experiência', 'Dono da Kaizen', 'Especialista em Barba'],
      servicos: ['Cortes', 'Barba', 'Coloração'],
      imagem: '/images/marco.png',
      horarios: { segunda: ['09:00', '10:00', '11:00', '14:00', '15:00', '16:00'], terca: [], quarta: ['09:00', '10:00', '11:00', '14:00', '15:00', '16:00'], quinta: ['09:00', '10:00', '11:00', '14:00', '15:00', '16:00'], sexta: ['09:00', '10:00', '11:00', '14:00', '15:00', '16:00'], sabado: ['09:00', '10:00', '14:00', '15:00'], domingo: ['10:00', '11:00', '15:00', '16:00'] }
    },
    { 
      id: 2, 
      uuid: '66266181-d06b-4f54-bcc9-12dccc100cb4',
      nome: 'Gabriel Little Kaizen', 
      especialidade: 'Especialista em Cortes',
      qualificacoes: ['Profissional certificado', 'Especialista em Permanente', 'Técnica moderna'],
      servicos: ['Cortes', 'Permanente', 'Lavagem'],
      imagem: '/images/gabriel.png',
      horarios: { segunda: ['10:00', '11:00', '14:00', '15:00'], terca: [], quarta: ['10:00', '11:00', '14:00', '15:00'], quinta: ['10:00', '11:00', '14:00', '15:00'], sexta: ['10:00', '11:00', '14:00', '15:00'], sabado: ['10:00', '14:00'], domingo: ['11:00', '14:00'] }
    },
    { 
      id: 3, 
      uuid: 'ad232428-9872-46db-82b3-27819ab353ff',
      nome: 'Neia', 
      especialidade: 'Especialista em Coloração e Estética',
      qualificacoes: ['Coloração avançada', 'Limpeza facial', 'Massagem facial'],
      servicos: ['Coloração', 'Alisamento', 'Estética'],
      imagem: '/images/neia.png',
      horarios: { segunda: ['09:00', '11:00', '15:00', '16:00', '17:00'], terca: [], quarta: ['09:00', '11:00', '15:00', '16:00', '17:00'], quinta: ['09:00', '11:00', '15:00', '16:00', '17:00'], sexta: ['09:00', '11:00', '15:00', '16:00', '17:00'], sabado: ['11:00', '15:00'], domingo: ['09:00', '16:00'] }
    },
  ];

  useEffect(() => {
    buscarHorariosOcupados();
  }, [mesAtual]);

  useEffect(() => {
    if (dadosAgendamento.email && dadosAgendamento.email.includes('@')) {
      buscarPontosCliente();
    }
  }, [dadosAgendamento.email]);

  const buscarPontosCliente = async () => {
    setCarregandoPontos(true);
    try {
      const { data: clientes } = await supabase
        .from('clientes')
        .select('id')
        .eq('email', dadosAgendamento.email);

      if (!clientes || clientes.length === 0) {
        setPontosCliente(0);
        setCarregandoPontos(false);
        return;
      }

      const cliente = clientes[0];

      const { data: agendamentos, error } = await supabase
        .from('agendamentos')
        .select('id')
        .eq('cliente_id', cliente.id)
        .eq('status', 'REALIZADO');

      if (error) throw error;

      const pontos = (agendamentos?.length || 0) * 2;
      setPontosCliente(pontos);
    } catch (error) {
      console.error('Erro ao buscar pontos:', error);
      setPontosCliente(0);
    } finally {
      setCarregandoPontos(false);
    }
  };

  const buscarHorariosOcupados = async () => {
    try {
      const ano = mesAtual.getFullYear();
      const mes = mesAtual.getMonth();

      const primeiroDia = new Date(ano, mes, 1);
      const ultimoDia = new Date(ano, mes + 1, 0);

      const dataInicio = primeiroDia.toISOString().split('T')[0];
      const dataFim = ultimoDia.toISOString().split('T')[0];

      const { data, error } = await supabase
        .from('agendamentos')
        .select('profissional_id, data_hora, status')
        .gte('data_hora', `${dataInicio}T00:00:00`)
        .lte('data_hora', `${dataFim}T23:59:59`)
        .in('status', ['CONFIRMADO', 'REALIZADO']);

      if (error) throw error;

      const ocupados = {};
      data.forEach(agendamento => {
        const profUUID = agendamento.profissional_id;
        const dataHora = agendamento.data_hora;

        if (!ocupados[profUUID]) {
          ocupados[profUUID] = [];
        }
        ocupados[profUUID].push(dataHora);
      });

      setHorariosOcupados(ocupados);
    } catch (error) {
      console.error('Erro ao buscar horários:', error);
    }
  };

  const getDiaSemana = (data) => {
    const dias = ['Domingo', 'Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado'];
    return dias[data.getDay()];
  };

  const getHorariosProfissional = (prof, data) => {
    const diaSemana = ['domingo', 'segunda', 'terca', 'quarta', 'quinta', 'sexta', 'sabado'][data.getDay()];
    const horariosBase = prof.horarios[diaSemana] || [];
    const horariosOcupadosDeste = horariosOcupados[prof.uuid] || [];

    return horariosBase.filter(h => {
      const dataHoraCompleta = `${data.toISOString().split('T')[0]}T${h}:00`;
      return !horariosOcupadosDeste.some(o => o.startsWith(dataHoraCompleta.substring(0, 16)));
    });
  };

  const calcularPrecoFinal = () => {
    if (!dadosAgendamento.servico) return 0;
    const servico = servicos.find(s => s.nome === dadosAgendamento.servico);
    if (!servico) return 0;
    let preco = servico.preco;
    if (usarPontos && pontosCliente >= 10) {
      preco -= 500;
    }
    return Math.max(0, preco);
  };

  const handleSelecionarDiaHorario = (data, prof, hora) => {
    setDiaHorarioSelecionado({ data, prof, hora });
    setDadosAgendamento({
      ...dadosAgendamento,
      data: data.toISOString().split('T')[0],
      profissional: prof.nome,
      hora: hora
    });
  };

  const handleConfirmarAgendamento = async () => {
    if (!dadosAgendamento.nome || !dadosAgendamento.email) {
      alert('⚠️ Preencha seu nome e email!');
      return;
    }

    if (!dadosAgendamento.servico) {
      alert('⚠️ Selecione um serviço!');
      return;
    }

    if (usarPontos && pontosCliente < 10) {
      alert('⚠️ Você não tem pontos suficientes para resgatar desconto!');
      return;
    }

    setCarregando(true);

    try {
      let clienteId = null;

      const { data: clientesExistentes } = await supabase
        .from('clientes')
        .select('id')
        .eq('email', dadosAgendamento.email);

      if (clientesExistentes && clientesExistentes.length > 0) {
        clienteId = clientesExistentes[0].id;
      } else {
        const { data: novoCliente, error: erroClienteInsert } = await supabase
          .from('clientes')
          .insert([
            {
              nome: dadosAgendamento.nome,
              email: dadosAgendamento.email,
              telefone: dadosAgendamento.telefone || null
            }
          ])
          .select('id')
          .single();

        if (erroClienteInsert) throw erroClienteInsert;
        clienteId = novoCliente.id;
      }

      const profissionalUUID = diaHorarioSelecionado.prof.uuid;
      const servicoSelecionado = servicos.find(s => s.nome === dadosAgendamento.servico);
      const servicoUUID = servicoSelecionado.uuid;
      const precoFinal = calcularPrecoFinal();

      const { error } = await supabase
        .from('agendamentos')
        .insert([
          {
            cliente_id: clienteId,
            profissional_id: profissionalUUID,
            servico_id: servicoUUID,
            data_hora: `${dadosAgendamento.data}T${dadosAgendamento.hora}:00`,
            status: 'CONFIRMADO',
            preco_final: precoFinal,
            observacoes: usarPontos ? 'Desconto de pontos de fidelidade aplicado (-¥500)' : null
          }
        ]);

      if (error) throw error;

      setAgendamentoConfirmado({
        numero: Math.floor(Math.random() * 100000),
        profissional: dadosAgendamento.profissional,
        servico: dadosAgendamento.servico,
        data: new Date(dadosAgendamento.data).toLocaleDateString('pt-BR'),
        hora: dadosAgendamento.hora,
        precoOriginal: servicoSelecionado.preco,
        precoFinal: precoFinal,
        desconto: usarPontos ? 500 : 0
      });

      setDadosAgendamento({ nome: '', email: '', telefone: '', profissional: '', hora: '', servico: '', data: '' });
      setAvisoPolítica(false);
      setUsarPontos(false);
      setPontosCliente(0);
      setDiaHorarioSelecionado(null);

      setTimeout(() => {
        setAgendamentoConfirmado(null);
        setAbaAtiva('servicos');
      }, 5000);

    } catch (error) {
      alert('❌ Erro ao agendar: ' + error.message);
    } finally {
      setCarregando(false);
    }
  };

  const handleAdicionarAvaliacao = (e) => {
    e.preventDefault();
    if (novaAvaliacao.nome && novaAvaliacao.texto) {
      const hoje = new Date().toISOString().split('T')[0];
      setAvaliacoes([...avaliacoes, {
        id: avaliacoes.length + 1,
        ...novaAvaliacao,
        data: hoje
      }]);
      setNovaAvaliacao({ nome: '', estrelas: 5, texto: '' });
      alert('✅ Avaliação enviada! Use o código AVALIACAOKAIZEN para ganhar 20% OFF');
    }
  };

  const renderizarEstrelas = (num) => {
    return '★'.repeat(num);
  };

  const gerarCalendario = () => {
    const ano = mesAtual.getFullYear();
    const mes = mesAtual.getMonth();

    const primeiroDia = new Date(ano, mes, 1);
    const ultimoDia = new Date(ano, mes + 1, 0);
    const diasMes = ultimoDia.getDate();
    const diaInicio = primeiroDia.getDay();

    const dias = [];
    for (let i = 0; i < diaInicio; i++) dias.push(null);
    for (let i = 1; i <= diasMes; i++) dias.push(new Date(ano, mes, i));
    return dias;
  };

  if (agendamentoConfirmado) {
    return (
      <div className="cliente-publico-container">
        <div style={{ 
          display: 'flex', 
          justifyContent: 'center', 
          alignItems: 'center', 
          minHeight: '100vh',
          background: 'linear-gradient(135deg, #1a1a1a 0%, #2d2d2d 50%, #1a1a1a 100%)'
        }}>
          <div style={{
            background: '#2d2d2d',
            border: '2px solid #d4af37',
            borderRadius: '12px',
            padding: '40px',
            textAlign: 'center',
            maxWidth: '500px'
          }}>
            <h2 style={{ color: '#d4af37', fontSize: '28px', marginBottom: '20px' }}>
              ✅ AGENDAMENTO CONFIRMADO!
            </h2>
            <div style={{ color: '#e8e8e8', fontSize: '16px', lineHeight: '1.8', marginBottom: '30px' }}>
              <p><strong>Número do Agendamento:</strong> #{agendamentoConfirmado.numero}</p>
              <p><strong>Profissional:</strong> {agendamentoConfirmado.profissional}</p>
              <p><strong>Serviço:</strong> {agendamentoConfirmado.servico}</p>
              <p><strong>Data:</strong> {agendamentoConfirmado.data}</p>
              <p><strong>Hora:</strong> {agendamentoConfirmado.hora}</p>
              {agendamentoConfirmado.desconto > 0 && (
                <>
                  <p style={{ color: '#4ade80' }}><strong>Preço Original:</strong> ¥{agendamentoConfirmado.precoOriginal.toLocaleString('ja-JP')}</p>
                  <p style={{ color: '#4ade80' }}><strong>Desconto (Pontos):</strong> -¥{agendamentoConfirmado.desconto.toLocaleString('ja-JP')}</p>
                  <p style={{ color: '#60a5fa', fontWeight: 'bold' }}><strong>Preço Final:</strong> ¥{agendamentoConfirmado.precoFinal.toLocaleString('ja-JP')}</p>
                </>
              )}
              {agendamentoConfirmado.desconto === 0 && (
                <p><strong>Preço:</strong> ¥{agendamentoConfirmado.precoFinal.toLocaleString('ja-JP')}</p>
              )}
            </div>
            <p style={{ color: '#999', fontSize: '13px', marginBottom: '20px', fontStyle: 'italic' }}>
              Confirmação foi enviada para seu email
            </p>
            <p style={{ color: '#d4af37', fontSize: '14px', fontWeight: 'bold' }}>
              ⏱️ Redirecionando em instantes...
            </p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="cliente-publico-container" style={{ background: '#1a1a1a', color: '#e8e8e8', minHeight: '100vh' }}>
      <header style={{ borderBottom: '3px solid #d4af37', padding: '20px', textAlign: 'center' }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '15px' }}>
          <img src="/images/logo.png" alt="Kaizen" style={{ width: '60px', height: '60px' }} />
          <div>
            <h1 style={{ color: '#d4af37', fontSize: '32px', margin: '0' }}>Kaizen Barber Shop</h1>
            <p style={{ color: '#999', margin: '0' }}>Premium Barbershop - Anjo, Aichi</p>
          </div>
        </div>
      </header>

      <nav style={{ display: 'flex', gap: '10px', padding: '20px', borderBottom: '1px solid #404040', overflowX: 'auto' }}>
        {[
          { id: 'servicos', label: '💈 Serviços' },
          { id: 'agendar', label: '📅 Agendar' },
          { id: 'endereco', label: '📍 Endereço' },
          { id: 'profissionais', label: '👥 Profissionais' },
          { id: 'fidelidade', label: '🎁 Fidelidade' },
          { id: 'avaliacoes', label: '★ Avaliações' },
        ].map((aba) => (
          <button 
            key={aba.id}
            onClick={() => setAbaAtiva(aba.id)}
            style={{
              padding: '10px 15px',
              background: abaAtiva === aba.id ? '#d4af37' : 'transparent',
              color: abaAtiva === aba.id ? '#1a1a1a' : '#d4af37',
              border: '1px solid #d4af37',
              borderRadius: '4px',
              cursor: 'pointer',
              fontWeight: 'bold',
              whiteSpace: 'nowrap'
            }}
          >
            {aba.label}
          </button>
        ))}
      </nav>

      <main style={{ padding: '30px', maxWidth: '1200px', margin: '0 auto' }}>

        {abaAtiva === 'servicos' && (
          <section>
            <h2 style={{ color: '#d4af37', marginBottom: '30px' }}>💈 Nossos Serviços</h2>
            <div style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))',
              gap: '20px'
            }}>
              {servicos.map((servico) => (
                <div key={servico.id} style={{
                  border: '1px solid #d4af37',
                  borderRadius: '8px',
                  overflow: 'hidden',
                  background: '#2d2d2d'
                }}>
                  <img src={servico.imagem} alt={servico.nome} style={{
                    width: '100%',
                    height: '250px',
                    objectFit: 'cover'
                  }} />
                  <div style={{ padding: '15px' }}>
                    <h3 style={{ color: '#d4af37', marginTop: '0' }}>{servico.nome}</h3>
                    <p style={{ color: '#999', fontSize: '14px', margin: '5px 0' }}>{servico.descricao}</p>
                    <p style={{ color: '#999', fontSize: '12px', margin: '5px 0' }}>⏱️ {servico.duracao}</p>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '15px' }}>
                      <span style={{ color: '#d4af37', fontWeight: 'bold', fontSize: '18px' }}>¥{servico.preco.toLocaleString('ja-JP')}</span>
                      <button 
                        onClick={() => {
                          setDadosAgendamento({ ...dadosAgendamento, servico: servico.nome });
                          setAbaAtiva('agendar');
                        }}
                        style={{
                          background: '#d4af37',
                          color: '#1a1a1a',
                          border: 'none',
                          padding: '8px 12px',
                          borderRadius: '4px',
                          fontWeight: 'bold',
                          cursor: 'pointer'
                        }}
                      >
                        Agendar
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </section>
        )}

        {abaAtiva === 'agendar' && (
          <section style={{
            backgroundImage: 'url(/images/interior.png)',
            backgroundSize: 'cover',
            backgroundPosition: 'center',
            backgroundAttachment: 'fixed',
            borderRadius: '12px',
            overflow: 'hidden',
            boxShadow: '0 0 30px rgba(212, 175, 55, 0.3)'
          }}>
            <div style={{
              background: 'rgba(26, 26, 26, 0.92)',
              padding: '30px',
              backdropFilter: 'blur(8px)'
            }}>
              <h2 style={{ color: '#d4af37', marginBottom: '20px' }}>📅 Calendário de Agendamentos</h2>

              <div style={{ display: 'flex', gap: '10px', alignItems: 'center', justifyContent: 'center', marginBottom: '20px' }}>
                <button 
                  onClick={() => setMesAtual(new Date(mesAtual.getFullYear(), mesAtual.getMonth() - 1))}
                  style={{ padding: '8px 16px', background: '#d4af37', color: '#1a1a1a', border: 'none', borderRadius: '4px', cursor: 'pointer', fontWeight: 'bold' }}
                >
                  ← Anterior
                </button>
                <span style={{ color: '#d4af37', fontWeight: 'bold', minWidth: '200px', textAlign: 'center', fontSize: '18px' }}>
                  {mesAtual.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' })}
                </span>
                <button 
                  onClick={() => setMesAtual(new Date(mesAtual.getFullYear(), mesAtual.getMonth() + 1))}
                  style={{ padding: '8px 16px', background: '#d4af37', color: '#1a1a1a', border: 'none', borderRadius: '4px', cursor: 'pointer', fontWeight: 'bold' }}
                >
                  Próximo →
                </button>
              </div>

              <div style={{
                display: 'grid',
                gridTemplateColumns: 'repeat(7, 1fr)',
                gap: '10px',
                marginBottom: '30px'
              }}>
                {['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sab'].map(dia => (
                  <div key={dia} style={{ textAlign: 'center', color: '#d4af37', fontWeight: 'bold', padding: '10px' }}>
                    {dia}
                  </div>
                ))}

                {gerarCalendario().map((data, idx) => {
                  if (!data) {
                    return <div key={`vazio-${idx}`} style={{ padding: '10px' }}></div>;
                  }

                  const dataStr = data.toISOString().split('T')[0];
                  const hoje = new Date();
                  const ehPassado = data < hoje && data.getDate() !== hoje.getDate();
                  const diaSemana = getDiaSemana(data);

                  return (
                    <div
                      key={dataStr}
                      style={{
                        border: '2px solid #d4af37',
                        padding: '10px',
                        borderRadius: '6px',
                        background: ehPassado ? 'rgba(26, 26, 26, 0.7)' : 'rgba(45, 45, 45, 0.8)',
                        minHeight: '140px',
                        cursor: ehPassado ? 'not-allowed' : 'pointer',
                        opacity: ehPassado ? 0.5 : 1,
                        backdropFilter: 'blur(4px)'
                      }}
                    >
                      <div style={{ color: '#d4af37', fontWeight: 'bold', marginBottom: '3px', fontSize: '14px' }}>
                        {data.getDate()}
                      </div>
                      <div style={{ color: '#999', fontWeight: 'bold', fontSize: '10px', marginBottom: '8px', borderBottom: '1px solid #404040', paddingBottom: '5px' }}>
                        {diaSemana}
                      </div>
                      {!ehPassado && (
                        <div style={{ fontSize: '10px' }}>
                          {profissionais.map(prof => {
                            const horarios = getHorariosProfissional(prof, data);
                            return horarios.length > 0 ? (
                              <div key={prof.id} style={{ marginBottom: '5px' }}>
                                <div style={{ color: '#4ade80', fontWeight: 'bold', fontSize: '9px' }}>{prof.nome}:</div>
                                <div style={{ color: '#e8e8e8', fontSize: '9px', display: 'flex', flexWrap: 'wrap', gap: '2px' }}>
                                  {horarios.map(h => (
                                    <button
                                      key={h}
                                      onClick={() => handleSelecionarDiaHorario(data, prof, h)}
                                      style={{
                                        background: '#4ade80',
                                        color: '#1a1a1a',
                                        border: 'none',
                                        borderRadius: '3px',
                                        padding: '2px 4px',
                                        fontSize: '8px',
                                        fontWeight: 'bold',
                                        cursor: 'pointer'
                                      }}
                                    >
                                      {h}
                                    </button>
                                  ))}
                                </div>
                              </div>
                            ) : null;
                          })}
                        </div>
                      )}
                      {ehPassado && (
                        <div style={{ color: '#999', fontSize: '10px' }}>Fechado</div>
                      )}
                    </div>
                  );
                })}
              </div>

              {diaHorarioSelecionado && (
                <div style={{
                  background: 'rgba(45, 45, 45, 0.95)',
                  border: '2px solid #d4af37',
                  borderRadius: '8px',
                  padding: '20px',
                  maxWidth: '500px',
                  margin: '0 auto',
                  backdropFilter: 'blur(10px)'
                }}>
                  <h3 style={{ color: '#d4af37' }}>📅 Resumo da Seleção</h3>
                  <p><strong>Dia:</strong> {diaHorarioSelecionado.data.getDate()} de {diaHorarioSelecionado.data.toLocaleDateString('pt-BR', { month: 'long' })} ({getDiaSemana(diaHorarioSelecionado.data)})</p>
                  <p><strong>Horário:</strong> {diaHorarioSelecionado.hora}</p>
                  <p><strong>Profissional:</strong> {diaHorarioSelecionado.prof.nome}</p>

                  <h4 style={{ color: '#d4af37', marginTop: '20px' }}>Dados do Agendamento</h4>
                  <input
                    type="text"
                    placeholder="Seu nome completo"
                    value={dadosAgendamento.nome}
                    onChange={(e) => setDadosAgendamento({...dadosAgendamento, nome: e.target.value})}
                    style={{ width: '100%', padding: '10px', marginBottom: '10px', borderRadius: '4px', border: '1px solid #404040', background: '#1a1a1a', color: '#e8e8e8', boxSizing: 'border-box' }}
                  />
                  <input
                    type="email"
                    placeholder="Seu email"
                    value={dadosAgendamento.email}
                    onChange={(e) => setDadosAgendamento({...dadosAgendamento, email: e.target.value})}
                    style={{ width: '100%', padding: '10px', marginBottom: '10px', borderRadius: '4px', border: '1px solid #404040', background: '#1a1a1a', color: '#e8e8e8', boxSizing: 'border-box' }}
                  />
                  <input
                    type="tel"
                    placeholder="Seu telefone (opcional)"
                    value={dadosAgendamento.telefone}
                    onChange={(e) => setDadosAgendamento({...dadosAgendamento, telefone: e.target.value})}
                    style={{ width: '100%', padding: '10px', marginBottom: '10px', borderRadius: '4px', border: '1px solid #404040', background: '#1a1a1a', color: '#e8e8e8', boxSizing: 'border-box' }}
                  />
                  <select
                    value={dadosAgendamento.servico}
                    onChange={(e) => setDadosAgendamento({...dadosAgendamento, servico: e.target.value})}
                    style={{ width: '100%', padding: '10px', marginBottom: '20px', borderRadius: '4px', border: '1px solid #404040', background: '#1a1a1a', color: '#e8e8e8', boxSizing: 'border-box' }}
                  >
                    <option value="">Selecione um serviço</option>
                    {servicos.map(s => (
                      <option key={s.id} value={s.nome}>{s.nome} - ¥{s.preco.toLocaleString('ja-JP')}</option>
                    ))}
                  </select>

                  {carregandoPontos ? (
                    <p style={{ color: '#d4af37' }}>⏳ Carregando seus pontos...</p>
                  ) : pontosCliente > 0 ? (
                    <div style={{ background: 'rgba(45, 61, 45, 0.8)', border: '1px solid #4ade80', borderRadius: '6px', padding: '15px', marginBottom: '20px' }}>
                      <h4 style={{ color: '#4ade80', marginBottom: '10px' }}>🎁 Seus Pontos de Fidelidade</h4>
                      <p>Você tem <strong style={{ color: '#4ade80', fontSize: '16px' }}>{pontosCliente} pontos</strong> acumulados!</p>

                      {pontosCliente >= 10 && (
                        <label style={{ display: 'flex', alignItems: 'center', gap: '10px', cursor: 'pointer', marginBottom: '10px' }}>
                          <input
                            type="checkbox"
                            checked={usarPontos}
                            onChange={(e) => setUsarPontos(e.target.checked)}
                            style={{ width: '18px', height: '18px', cursor: 'pointer' }}
                          />
                          <span>✨ Usar 10 pontos para <strong>-¥500 desconto</strong></span>
                        </label>
                      )}

                      {pontosCliente < 10 && (
                        <p style={{ color: '#999', fontSize: '12px' }}>
                          Você precisa de 10 pontos para resgatar um desconto. Faltam ainda <strong>{10 - pontosCliente} pontos</strong>!
                        </p>
                      )}

                      {usarPontos && pontosCliente >= 10 && (
                        <div style={{ background: 'rgba(26, 42, 26, 0.8)', padding: '10px', borderRadius: '4px', marginTop: '10px' }}>
                          <p style={{ color: '#4ade80', fontSize: '14px', fontWeight: 'bold' }}>
                            💰 Preço Original: ¥{servicos.find(s => s.nome === dadosAgendamento.servico)?.preco.toLocaleString('ja-JP') || '-'}
                          </p>
                          <p style={{ color: '#4ade80', fontSize: '14px', fontWeight: 'bold' }}>
                            💳 Após Desconto: ¥{calcularPrecoFinal().toLocaleString('ja-JP')}
                          </p>
                        </div>
                      )}
                    </div>
                  ) : (
                    <p style={{ color: '#999', fontSize: '12px', marginBottom: '15px' }}>
                      Você ainda não tem pontos. Realize seu primeiro agendamento para começar a acumular!
                    </p>
                  )}

                  <h4 style={{ color: '#d4af37', marginTop: '20px' }}>⚠️ Política de Cancelamento</h4>
                  <p style={{ fontSize: '12px', color: '#999' }}>
                    ❌ SEM JUSTIFICATIVA: Se não comparecer sem avisar, você pagará o valor INTEGRAL do serviço<br/>
                    ✅ COM AVISO PRÉVIO: Se avisar com antecedência, não há cobrança<br/>
                    ⚠️ COM JUSTIFICATIVA: Se faltar com justificativa válida, desconto de 50%
                  </p>

                  <div style={{ display: 'flex', gap: '10px', marginTop: '20px' }}>
                    <button 
                      onClick={() => setDiaHorarioSelecionado(null)}
                      style={{
                        background: 'transparent',
                        color: '#d4af37',
                        border: '1px solid #d4af37',
                        padding: '10px 20px',
                        borderRadius: '4px',
                        fontWeight: 'bold',
                        cursor: 'pointer'
                      }}
                    >
                      Cancelar
                    </button>
                    <button 
                      onClick={handleConfirmarAgendamento}
                      disabled={carregando}
                      style={{
                        flex: 1,
                        background: '#d4af37',
                        color: '#1a1a1a',
                        border: 'none',
                        padding: '10px',
                        borderRadius: '4px',
                        fontWeight: 'bold',
                        cursor: carregando ? 'wait' : 'pointer'
                      }}
                    >
                      {carregando ? '⏳ Agendando...' : '✅ Confirmar Agendamento'}
                    </button>
                  </div>
                </div>
              )}
            </div>
          </section>
        )}

        {abaAtiva === 'endereco' && (
          <section>
            <h2 style={{ color: '#d4af37' }}>📍 Nossa Localização</h2>
            <div style={{ maxWidth: '600px' }}>
              <div style={{ marginBottom: '20px' }}>
                <h3>Kaizen Barber Shop</h3>
                <p><strong>Endereço Completo:</strong><br />
                Aichi-Ken Anjo-Shi<br />
                Hamatomi-Cho 4-17<br />
                San City Oomy 302</p>
                <p><strong>Referência:</strong><br />
                Do outro lado da rua em relação ao McDonald's do Korona World</p>
                <a href="https://www.google.com/maps/search/Anjo+Aichi+Hamatomi+Cho+4-17/@35.01,-136.91,15z" target="_blank" rel="noopener noreferrer" style={{ color: '#d4af37', textDecoration: 'none', fontWeight: 'bold' }}>
                  🗺️ Ver no Google Maps
                </a>
              </div>
              <div style={{
                display: 'grid',
                gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
                gap: '15px'
              }}>
                <img src="/images/fachada.png" alt="Fachada" style={{ width: '100%', height: '200px', objectFit: 'cover', borderRadius: '8px' }} />
                <img src="/images/interior.png" alt="Interior" style={{ width: '100%', height: '200px', objectFit: 'cover', borderRadius: '8px' }} />
                <img src="/images/ambiente.png" alt="Ambiente" style={{ width: '100%', height: '200px', objectFit: 'cover', borderRadius: '8px' }} />
                <img src="/images/detalhes.png" alt="Detalhes" style={{ width: '100%', height: '200px', objectFit: 'cover', borderRadius: '8px' }} />
              </div>
            </div>
          </section>
        )}

        {abaAtiva === 'profissionais' && (
          <section>
            <h2 style={{ color: '#d4af37', marginBottom: '30px' }}>👥 Nossos Profissionais</h2>
            <div style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))',
              gap: '20px'
            }}>
              {profissionais.map((prof) => (
                <div key={prof.id} style={{
                  border: '1px solid #d4af37',
                  borderRadius: '8px',
                  overflow: 'hidden',
                  background: '#2d2d2d'
                }}>
                  <img src={prof.imagem} alt={prof.nome} style={{
                    width: '100%',
                    height: '250px',
                    objectFit: 'cover'
                  }} />
                  <div style={{ padding: '15px' }}>
                    <h3 style={{ color: '#d4af37', marginTop: '0' }}>{prof.nome}</h3>
                    <p style={{ color: '#999', fontSize: '14px', margin: '5px 0' }}>{prof.especialidade}</p>
                    <div style={{ marginTop: '10px' }}>
                      <strong style={{ color: '#d4af37' }}>Qualificações:</strong>
                      {prof.qualificacoes.map((qual, idx) => (
                        <p key={idx} style={{ color: '#e8e8e8', margin: '3px 0', fontSize: '13px' }}>✓ {qual}</p>
                      ))}
                    </div>
                    <div style={{ marginTop: '10px' }}>
                      <strong style={{ color: '#d4af37' }}>Serviços:</strong>
                      <p style={{ color: '#e8e8e8', margin: '3px 0', fontSize: '13px' }}>{prof.servicos.join(', ')}</p>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </section>
        )}

        {abaAtiva === 'fidelidade' && (
          <section>
            <h2 style={{ color: '#d4af37' }}>🎁 Programa de Fidelidade</h2>
            <div style={{
              background: '#2d2d2d',
              border: '1px solid #d4af37',
              borderRadius: '8px',
              padding: '20px',
              maxWidth: '600px'
            }}>
              <h3 style={{ color: '#d4af37' }}>Ganhe pontos a cada visita!</h3>
              <p>✅ <strong>2 pontos</strong> por cada serviço realizado</p>
              <p>✅ <strong>10 pontos</strong> = <strong>¥500</strong> de desconto</p>
              <p>✅ Resgate automático no próximo agendamento</p>
              <p>✅ Válido por <strong>3 meses</strong></p>
              <p>✅ <strong>Intransferível</strong> (pessoal)</p>
              <p style={{ color: '#d4af37', marginTop: '15px', fontWeight: 'bold' }}>
                Você já é membro automaticamente ao fazer seu primeiro agendamento! 🎉
              </p>
            </div>
          </section>
        )}

        {abaAtiva === 'avaliacoes' && (
          <section>
            <h2 style={{ color: '#d4af37' }}>★ Avaliações</h2>

            <div style={{
              background: '#2d2d2d',
              border: '1px solid #d4af37',
              borderRadius: '8px',
              padding: '20px',
              marginBottom: '30px',
              maxWidth: '600px'
            }}>
              <h3 style={{ color: '#d4af37' }}>📝 Deixe sua avaliação!</h3>
              <p style={{ color: '#999', fontSize: '14px' }}>✨ Ganhe 20% de desconto ao avaliar serviços, profissionais e ambiente</p>
              <form onSubmit={(e) => { e.preventDefault(); handleAdicionarAvaliacao(e); }}>
                <input
                  type="text"
                  placeholder="Seu nome"
                  value={novaAvaliacao.nome}
                  onChange={(e) => setNovaAvaliacao({...novaAvaliacao, nome: e.target.value})}
                  style={{ width: '100%', padding: '10px', marginBottom: '10px', borderRadius: '4px', border: '1px solid #404040', background: '#1a1a1a', color: '#e8e8e8', boxSizing: 'border-box' }}
                  required
                />
                <select
                  value={novaAvaliacao.estrelas}
                  onChange={(e) => setNovaAvaliacao({...novaAvaliacao, estrelas: parseInt(e.target.value)})}
                  style={{ width: '100%', padding: '10px', marginBottom: '10px', borderRadius: '4px', border: '1px solid #404040', background: '#1a1a1a', color: '#e8e8e8', boxSizing: 'border-box' }}
                >
                  <option value="1">★ 1 estrela</option>
                  <option value="2">★★ 2 estrelas</option>
                  <option value="3">★★★ 3 estrelas</option>
                  <option value="4">★★★★ 4 estrelas</option>
                  <option value="5">★★★★★ 5 estrelas</option>
                </select>
                <textarea
                  placeholder="Sua avaliação (serviço, profissional, ambiente)"
                  value={novaAvaliacao.texto}
                  onChange={(e) => setNovaAvaliacao({...novaAvaliacao, texto: e.target.value})}
                  style={{ width: '100%', padding: '10px', marginBottom: '10px', borderRadius: '4px', border: '1px solid #404040', background: '#1a1a1a', color: '#e8e8e8', boxSizing: 'border-box', minHeight: '80px' }}
                  required
                ></textarea>
                <button type="submit" style={{
                  background: '#d4af37',
                  color: '#1a1a1a',
                  border: 'none',
                  padding: '10px 20px',
                  borderRadius: '4px',
                  fontWeight: 'bold',
                  cursor: 'pointer',
                  width: '100%'
                }}>
                  Enviar Avaliação - Ganhar 20% OFF
                </button>
              </form>
            </div>

            <div>
              <h3 style={{ color: '#d4af37' }}>Avaliações Recentes</h3>
              {avaliacoes.map((avaliacao) => (
                <div key={avaliacao.id} style={{
                  border: '1px solid #404040',
                  borderRadius: '6px',
                  padding: '15px',
                  marginBottom: '15px',
                  background: '#2d2d2d'
                }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '10px' }}>
                    <h4 style={{ margin: '0', color: '#e8e8e8' }}>{avaliacao.nome}</h4>
                    <span style={{ color: '#d4af37', fontSize: '16px' }}>{renderizarEstrelas(avaliacao.estrelas)}</span>
                  </div>
                  <p style={{ color: '#e8e8e8', margin: '10px 0' }}>{avaliacao.texto}</p>
                  <p style={{ color: '#999', fontSize: '12px', margin: '0' }}>{avaliacao.data}</p>
                </div>
              ))}
            </div>
          </section>
        )}
      </main>

      <footer style={{ borderTop: '1px solid #404040', padding: '20px', textAlign: 'center', color: '#999' }}>
        <p>&copy; 2026 Kaizen Barber Shop. Todos os direitos reservados.</p>
      </footer>
    </div>
  );
}

export default ClientePublico;
